import json, re
from pathlib import Path

analysis_path = Path('/root/mailer_policy_analysis.json')
summary_path = Path('/root/mailer_policy_summary.md')
analysis = json.loads(analysis_path.read_text())
errors = []
expected_root = ['assumptions', 'medications', 'totals', 'recommendation']
expected_med_keys = [
    'medication', 'price_per_1000_doses_usd', 'mailer_format', 'mailer_cost_usd',
    'base_payment_per_fill_150_patients_usd', 'service_fee_per_fill_150_patients_usd',
    'total_payment_per_fill_150_patients_usd', 'annual_drug_cost_45_day_usd',
    'annual_drug_cost_90_day_usd', 'annual_mailer_cost_45_day_usd',
    'annual_mailer_cost_90_day_usd', 'annual_payment_45_day_usd',
    'annual_payment_90_day_usd', 'annual_margin_45_day_usd',
    'annual_margin_90_day_usd', 'annual_margin_difference_90_minus_45_usd'
]
expected_totals = [
    'total_annual_margin_45_day_usd',
    'total_annual_margin_90_day_usd',
    'total_annual_margin_difference_90_minus_45_usd',
    'absolute_total_margin_difference_usd'
]
if list(analysis.keys()) != expected_root:
    errors.append(f'root keys {list(analysis.keys())} != {expected_root}')
meds = analysis.get('medications', [])
med_names = [m.get('medication') for m in meds]
if med_names != sorted(med_names):
    errors.append('medications are not alphabetically sorted')
for i, med in enumerate(meds):
    if list(med.keys()) != expected_med_keys:
        errors.append(f'medication {i} keys mismatch: {list(med.keys())}')
    for k, v in med.items():
        if k.endswith('_usd') and not isinstance(v, (int, float)):
            errors.append(f'{med.get("medication")}.{k} is not numeric')
        if k.endswith('_usd') and isinstance(v, (int, float)) and round(v, 2) != v:
            errors.append(f'{med.get("medication")}.{k} not rounded to 2 decimals: {v!r}')
if list(analysis.get('totals', {}).keys()) != expected_totals:
    errors.append(f'totals keys mismatch: {list(analysis.get("totals", {}).keys())}')
for k, v in analysis.get('totals', {}).items():
    if not isinstance(v, (int, float)) or round(v, 2) != v:
        errors.append(f'totals.{k} invalid currency value: {v!r}')
if list(analysis.get('recommendation', {}).keys()) != ['decision', 'justification']:
    errors.append(f'recommendation keys mismatch: {list(analysis.get("recommendation", {}).keys())}')
if analysis.get('recommendation', {}).get('decision') not in {'shift_to_90_day','keep_45_day'}:
    errors.append('invalid decision slug')
summary_lines = [line for line in summary_path.read_text().splitlines() if line.strip()]
if not (4 <= len(summary_lines) <= 8):
    errors.append(f'summary has {len(summary_lines)} non-empty lines')
required_summary_patterns = [
    r'^Total 45-day annual margin: \\$-?\\d+\\.\\d{2}$',
    r'^Total 90-day annual margin: \\$-?\\d+\\.\\d{2}$',
    r'^Absolute margin difference: \\$\\d+\\.\\d{2}$',
    r'^Recommendation: (shift_to_90_day|keep_45_day)$',
]
for pattern in required_summary_patterns:
    if not any(re.match(pattern, line) for line in summary_lines):
        errors.append(f'summary missing pattern: {pattern}')
if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('-', e)
    raise SystemExit(1)
print('VALIDATION PASSED')
print('root_keys=', list(analysis.keys()))
print('medications_sorted=', med_names)
print('totals=', analysis['totals'])
print('decision=', analysis['recommendation']['decision'])
print('summary_non_empty_lines=', len(summary_lines))"}

